#define iterations 13
#define formuparam 0.53

#define volsteps 20
#define stepsize 0.1

#define zoom   0.800
#define tile   0.850
#define speed  0.000 

#define brightness 0.0015
#define darkmatter 0.300
#define distfading 0.730
#define saturation 0.850

#define GAMMA (2.2)

vec3 ToLinear( in vec3 col )
{
	// simulate a monitor, converting colour values into light values
	return pow( col, vec3(GAMMA) );
}

vec3 ToGamma( in vec3 col )
{
	// convert back into colour values, so the correct light will come out of the monitor
	return pow( col, vec3(1.0/GAMMA) );
}

vec4 Noise( in ivec2 x )
{
	return texture( iChannel0, (vec2(x)+0.5)/256.0, -100.0 );
}

vec4 Rand( in int x )
{
	vec2 uv;
	uv.x = (float(x)+0.5)/256.0;
	uv.y = (floor(uv.x)+0.5)/256.0;
	return texture( iChannel0, uv, -100.0 );
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	//get coords and direction
	vec2 uv=fragCoord.xy/iResolution.xy-.5;

	uv.y*=iResolution.y/iResolution.x;
     uv/=-1.+uv.y*4.1;

	vec3 dir=vec3(uv*zoom,1.);

	float time=iTime*speed+.25;

	//mouse rotation
	float a1=iTime*0.02;

	mat2 rot1=mat2(cos(a1),sin(a1),-sin(a1),cos(a1));

vec3 ray;
	ray.xy = 2.0*(fragCoord.xy-iResolution.xy*.5)/iResolution.x;
	ray.z = 1.0;

	float offset = -iTime*.15;	
	float speed2 = (cos(offset)+1.0)*2.0;
	float speed3 = speed2+.1;
	offset += sin(offset)*.96;
	offset *= 2.0;


	vec3 col = vec3(0);

	vec3 stp = ray/max(abs(ray.x),abs(ray.y));

	vec3 pos = 2.0*stp+.5;
	for ( int i=0; i < 20; i++ )
	{
		float z = Noise(ivec2(pos.xy+cos(iTime))).x;
		z = fract(z-offset);
		float d = 50.0*z-pos.z;
		float w = pow(max(0.0,1.0-8.0*length(fract(pos.xy)-.5)),2.0);
		vec3 c = max(vec3(0),vec3(1.0-abs(d+speed2*.5)/speed3,1.0-abs(d)/speed3,1.0-abs(d-speed2*.5)/speed));
		col += 1.5*(1.0-z)*c*w;
		pos += stp;
	}

	vec3 from=vec3(1.,.5,0.5);
 vec2 uv3 = fragCoord / iResolution.xy;

	uv.y*=iResolution.y/iResolution.x;
    vec2 center = vec2(0.5, 0.5);
    vec2 offset3 = uv3 - center;
    float angle = 0.5 ;  // rotation speed
    float s3 = sin(angle);
    float c3 = cos(angle);
    mat2 rotate = mat2(c3, -s3,

	              s3,  c3);

                    vec2 cPos = -1.0 + 2.0 * fragCoord.xy / iResolution.xy;

    cPos.x+=0.2*cos(iTime);
      cPos.y+=0.2*sin(iTime);
    // distance of current pixel from center
	float cLength = length(cPos);


    offset3 = rotate * offset3;
    uv3 = offset3 + center;
     float baseScale = 3.0;
    float scaleVariation = 70.0 ;
    float scale = baseScale + scaleVariation;
      vec2 pix = floor(uv3 * scale)/scale;

     uv3 *= (cPos/cLength)*cos(cLength*12.0-iTime*3.0) * 0.13;





    vec4 o=fragColor;
    vec2 u=fragCoord;
vec3 c = iResolution;
    float i, t = .005*iTime;
    u = 0.7*(u+u-c.xy)/c.y + t;   
    for (o *= i; ++i<24.; o = sqrt(o*o+.7)*.99) 
        u *= -.1*mat2(5, 11, -11, 5), // 1.2*rot(2)
        u += cos(u.yx/.5+ .4*i*o.xz)*.023*i + t/i,
        c = cos(3.+vec3(cos(u*1e2),1)/10.+o.x*i/9.+u.x*.4*i+sin(u.y*i)),
        o.rgb += c*pow(c*c, vec3(1.,1.0,1))/pow(i,i/43.),
        u += sin(u.yx)*o.z*.13;
        o.rgb+=vec3(0.1,0.5,4.3);
    o = 1.-exp(-.018*o*o*o.r);



	//volumetric rendering
	float s=0.1,fade=1.;
	vec3 v=vec3(0.);

	for (int r=0; r<volsteps; r++) {
		vec3 p=from+s*dir*.5;
 p.xy *= (cPos/cLength)*cos(cLength*12.0-iTime*1.20) * 0.13;
        p.xy+=pix;
		p = abs(vec3(tile)-mod(p,vec3(tile*2.))); // tiling fold
		float pa,a=pa=0.;
		for (int i=0; i<iterations; i++) { 
			p=abs(p)/dot(p,p)-formuparam;
            	p.xy*=rot1;// the magic formula
			a+=abs(length(p)-pa); // absolute sum of average change
			pa=length(p);
		}
		float dm=max(0.,darkmatter-a*a*.001); //dark matter
		a*=a*a; // add contrast
		if (r>6) fade*=1.3-dm; // dark matter, don't render near
		//v+=vec3(dm,dm*.5,0.);
		v+=fade;
		v+=vec3(s,s*s,s*s*s*s)*a*brightness*fade; // coloring based on distance
		fade*=distfading; // distance fading
		s+=stepsize;
	}
	v=mix(vec3(length(v)),v,saturation); //color adjust
	fragColor = vec4(v*.05*o.xyz*1.01,1.);	

}
